def draw(grid, centers):
 n=len(grid); m=len(grid[0]); orig=[r[:] for r in grid]; out=[r[:] for r in grid]; cp={(r,c) for r,c,v in centers}
 for r,c,v in centers:
  for dr in (-1,1):
   rr=r+dr
   if 0<=rr<n and orig[rr][c]==3: rr+=dr
   while 0<=rr<n:
    if orig[rr][c]==3 or (rr,c) in cp: break
    out[rr][c]=v; rr+=dr
 for r,c,v in centers:
  for dc in (-1,1):
   cc=c+dc
   if 0<=cc<m and orig[r][cc]==3: cc+=dc
   while 0<=cc<m:
    if orig[r][cc]==3 or (r,cc) in cp: break
    if out[r][cc]==0: out[r][cc]=v
    cc+=dc
 return out
